\begin{aligned}
\mathrm{IsNaturalIso}(\eta,F,G)&\leftrightarrow\mathrm{IsNatural}(\eta,F,G)\land\forall A\in\mathrm{Ob}(\mathcal C)\ \mathrm{IsIso}(\eta_A),\\
\mathrm{IsFaithful}(F)&\leftrightarrow\forall A,B\in\mathrm{Ob}(\mathcal C)\ \forall f,g\in\mathrm{Hom}_{\mathcal C}(A,B)\ (F(f)=F(g)\to f=g),\\
\mathrm{IsFull}(F)&\leftrightarrow\forall A,B\in\mathrm{Ob}(\mathcal C)\ \forall h\in\mathrm{Hom}_{\mathcal D}(F(A),F(B))\ \exists f\in\mathrm{Hom}_{\mathcal C}(A,B)\ (F(f)=h),\\
\mathrm{IsFullyFaithful}(F)&\leftrightarrow\mathrm{IsFaithful}(F)\land\mathrm{IsFull}(F).
\end{aligned}
